namespace FrameForge.Core;

public sealed record SetupGuide(string Title,string Summary,string Group,string Steps,string? Control=null,Vendor Vendor=Vendor.Unknown);
public static class SetupGuides
{
    public static IReadOnlyList<SetupGuide> All {get;}=[
        new("Use your screen's full refresh rate","A screen left at 60 Hz cannot show the extra frames your PC is producing.","Windows","Open Advanced display, select your gaming screen, then choose its highest supported refresh rate. Confirm the screen still works correctly.","display"),
        new("Faster windowed games","Windows 11 can reduce display delay in compatible windowed DirectX 10/11 games.","Windows","Open Graphics, then Default settings. Compare Optimizations for windowed games on and off. Restart the game after a change.","graphics"),
        new("Choose the gaming graphics card","Useful when a laptop or PC has more than one graphics chip.","Windows","In Graphics, add the game's actual executable, open Options and choose High performance. A single-GPU PC usually gains nothing.","graphics"),
        new("Fewer apps starting with Windows","Stops optional apps from using memory and running in the background after login.","Windows","Open Startup apps. Turn off only apps you recognize and do not need. Keep drivers, security tools and unfamiliar items enabled.","startup"),
        new("Keep chipset drivers current","Can fix platform bugs and helps Windows use supported hardware behavior.","Windows","Use AMD's support site for your exact motherboard chipset. Note the current driver, read the release notes and restart after installation.","amd",Vendor.Amd),
        new("Check Smart Access Memory","Lets the processor reach a larger part of graphics memory at once. Results vary by game.","AMD","Check Smart Access Memory in AMD Software. Firmware support is required. Use the motherboard maker's instructions; do not blindly change boot or CSM settings.","amd",Vendor.Amd),
        new("Compare V-Sync on and off","Off can reduce waiting for the screen, but may cause tearing.","Fortnite","Open Fortnite Video settings and test V-Sync Off. If tearing bothers you, compare a stable frame limit with FreeSync. Change one setting at a time."),
        new("Performance Mode or DirectX 12?","The best rendering mode depends on the game scene and your PC.","Fortnite","Run the same route or replay in each mode. Let shaders finish building first. Compare smoothness and 1% lows, not only average FPS."),
        new("Lower shadows","Reduces work for the graphics card when the game exposes this setting.","Fortnite","In Graphics Quality, choose Shadows Off or Low. Check that important scene details remain easy to see."),
        new("Lower effects and post-processing","Reduces decorative effects and can leave more graphics power for busy fights.","Fortnite","Set Effects and Post Processing to Low where available. Compare the same scene and keep the image clear enough to play."),
        new("Turn off motion blur","Makes movement easier to see; it is mainly an image-clarity choice.","Fortnite","Open Video settings and turn Motion Blur off if the setting is available. It does not guarantee lower input delay."),
        new("Choose a steady frame limit","A frame rate you can hold can feel steadier than an unlimited rate that keeps dropping.","Fortnite","Test a few realistic FPS limits using the same route. Compare frame-time spikes, heat and input feel. There is no single best cap for every monitor."),
        new("Show the game's FPS counter","Lets you check the result of a change instead of guessing.","Fortnite","Turn on Show FPS in Video settings. For detailed comparisons, export measured frame times and use FrameForge's benchmark view."),
        new("Use a stable graphics driver","Driver fixes can help bugs or stutters in particular games.","AMD","Check AMD Software or the official support page. Record your current version first. A newer optional driver is not always better for every game.","amd",Vendor.Amd),
        new("Review Radeon Chill","Chill changes frame rate with activity. It can conflict with a steady competitive cap.","AMD","In AMD Software's Fortnite profile, compare Radeon Chill Off. Keep it for games where you prefer lower heat or power use.",null,Vendor.Amd),
        new("Let the game control V-Sync","Avoid an unwanted driver override fighting your in-game setting.","AMD","In the game's AMD Software profile, set Wait for Vertical Refresh to use the application setting. Test the in-game setting separately.",null,Vendor.Amd),
        new("Test Enhanced Sync separately","May reduce tearing in some setups, but can also feel worse.","AMD","Compare Enhanced Sync by itself before combining it with other sync options. Keep the simplest setup that feels smooth and consistent.",null,Vendor.Amd),
        new("Try FreeSync","Matches a supported screen's refresh timing to the game to reduce tearing.","AMD","Enable FreeSync in the monitor menu and AMD Software if supported. Confirm the correct monitor and compare a steady frame cap.",null,Vendor.Amd),
        new("Switch off unused AMD overlays","Avoid unused replay recording, overlays and pop-ups while playing.","AMD","In AMD Software, review overlay, instant replay, desktop recording and notifications. Keep any recording or measurement features you need.",null,Vendor.Amd),
        new("Keep the shader cache","Saved shader work can prevent repeated loading stutters.","AMD","Leave the cache enabled. Reset it through AMD Software only when troubleshooting a reproducible issue; expect warm-up stutters afterwards.",null,Vendor.Amd),
        new("Use a reliable mouse connection","A stable cable or well-placed wireless receiver helps avoid missed or uneven input.","Mouse","Use a reliable motherboard USB port. For wireless, keep the receiver close to the mouse and away from interference. Compare dropouts before buying anything."),
        new("Test mouse polling rate","Higher rates send more mouse updates, but extreme rates can add CPU work.","Mouse","Use your mouse's own software. Compare its stable default with 1000 Hz or higher supported rates. Keep the rate that stays smooth in your game."),
        new("Avoid an unreliable USB hub","A direct port is a useful check for mouse dropouts or connection problems.","Mouse","Try the mouse or receiver directly in a motherboard port. Do not randomly disable USB power-saving features when there is no problem."),
        new("Reduce Discord interruptions","Discord's overlay and automatic startup are optional; voice chat can still work.","Less clutter","In Discord, review Game Overlay. Use Startup apps to stop automatic login launch if you do not need it.","startup"),
        new("Hide Widgets and news","Removes an optional taskbar panel and its distractions.","Less clutter","Open Taskbar settings and turn Widgets off if available. Expect little or no change in game FPS.","taskbar"),
        new("Use Windows storage cleanup","Reviews old temporary files so you can free space without touching game saves.","Storage","Open Storage Sense or Temporary files. Review every category and leave Downloads unchecked unless you intend to delete those files.","storage"),
        new("Let Windows maintain your SSD","Windows can send the SSD cleanup commands it needs to maintain storage.","Storage","Open Optimize Drives, check the drive type and use Windows' own schedule. Do not repeatedly defragment an SSD with third-party tools."),
        new("Try Ethernet","A cable often has fewer Wi-Fi interference spikes and lost packets.","Network","Connect to the router by cable when practical. It cannot change the distance to the game server. Do not disable your only working connection.","network"),
        new("Check ping when the connection is busy","Router queues can increase delay when downloads or uploads fill the line.","Network","Compare idle ping with ping during your normal busy connection. If it rises sharply, consult the router's instructions for SQM or QoS, then retest."),
        new("DNS is for finding servers","Changing DNS can help lookups, but usually does not lower ping after joining a match.","Network","Change DNS only to solve a lookup or reliability problem. FrameForge does not apply a so-called gaming DNS automatically.","network")
